1	/**
2	 * Durable pi-ai replay metadata and assistant-history reconstruction.
3	 *
4	 * Harness content remains the durable source for text and tool calls. This
5	 * module stores only the provider-native metadata needed to reconstruct a
6	 * pi-ai assistant message on a later request.
7	 *
8	 * @module dsh-llm-pi-ai/replay
9	 */
10	
11	import { LlmError } from '@deepseek-ai/dsh-llm'
12	import type { Message, ModelMessageSource } from '@deepseek-ai/dsh-llm'
13	import type { Api, AssistantMessage, Usage as PiUsage } from '@earendil-works/pi-ai'
14	
15	type PiAiReplayBlock =
16	  | { type: 'text'; textSignature?: string }
17	  | { type: 'reasoning'; thinkingSignature?: string; redacted?: boolean }
18	  | { type: 'tool-call'; thoughtSignature?: string }
19	
20	/** Versioned adapter-private projection required to replay a pi-ai response. */
21	export interface PiAiReplayState {
22	  kind: 'pi-ai'
23	  version: 1
24	  api: Api
25	  provider: string
26	  model: string
27	  responseModel?: string
28	  responseId?: string
29	  stopReason: AssistantMessage['stopReason']
30	  blocks: PiAiReplayBlock[]
31	}
32	
33	/** Parse tool-call argument JSON; tolerate model malformations with {}. */
34	function parseArguments(raw: string): Record<string, unknown> {
35	  try {
36	    const parsed: unknown = JSON.parse(raw)
37	    if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
38	      return parsed as Record<string, unknown>
39	    }
40	  } catch {
41	    // fall through
42	  }
43	  return {}
44	}
45	
46	/** Construct the zero usage value required by historical pi-ai messages. */
47	function emptyPiUsage(): PiUsage {
48	  return {
49	    input: 0,
50	    output: 0,
51	    cacheRead: 0,
52	    cacheWrite: 0,
53	    totalTokens: 0,
54	    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
55	  }
56	}
57	
58	/**
59	 * Project a successful pi-ai response into the minimal durable replay state.
60	 * @param message - completed native pi-ai assistant response.
61	 * @returns the versioned lossless-JSON replay projection.
62	 */
63	export function toPiReplayState(message: AssistantMessage): PiAiReplayState {
64	  return {
65	    kind: 'pi-ai',
66	    version: 1,
67	    api: message.api,
68	    provider: message.provider,
69	    model: message.model,
70	    ...message.responseModel === undefined ? {} : { responseModel: message.responseModel },
71	    ...message.responseId === undefined ? {} : { responseId: message.responseId },
72	    stopReason: message.stopReason,
73	    blocks: message.content.map((block): PiAiReplayBlock => {
74	      switch (block.type) {
75	        case 'text': return {
76	          type: 'text',
77	          ...block.textSignature === undefined ? {} : { textSignature: block.textSignature },
78	        }
79	        case 'thinking': return {
80	          type: 'reasoning',
81	          ...block.thinkingSignature === undefined ? {} : { thinkingSignature: block.thinkingSignature },
82	          ...block.redacted === undefined ? {} : { redacted: block.redacted },
83	        }
84	        case 'toolCall': return {
85	          type: 'tool-call',
86	          ...block.thoughtSignature === undefined ? {} : { thoughtSignature: block.thoughtSignature },
87	        }
88	      }
89	    }),
90	  }
91	}
92	
93	function invalidReplay(message: string): never {
94	  throw new LlmError(`invalid pi-ai replay state: ${message}`, 'INVALID_REPLAY_STATE')
95	}
96	
97	/** Validate the adapter-private state before it reaches pi-ai. */
98	function readReplayState(value: unknown): PiAiReplayState {
99	  if (typeof value !== 'object' || value === null || Array.isArray(value)) return invalidReplay('expected an object')
100	  const state = value as Record<string, unknown>
101	  if (state['kind'] !== 'pi-ai') return invalidReplay('unknown state kind')
102	  if (state['version'] !== 1) return invalidReplay(`unsupported version ${String(state['version'])}`)
103	  for (const key of ['api', 'provider', 'model'] as const) {
104	    if (typeof state[key] !== 'string' || state[key].length === 0) return invalidReplay(`${key} must be a non-empty string`)
105	  }
106	  if (!['stop', 'length', 'toolUse', 'error', 'aborted'].includes(String(state['stopReason']))) {
107	    return invalidReplay('unknown stopReason')
108	  }
109	  if (state['responseModel'] !== undefined && typeof state['responseModel'] !== 'string') return invalidReplay('responseModel must be a string')
110	  if (state['responseId'] !== undefined && typeof state['responseId'] !== 'string') return invalidReplay('responseId must be a string')
111	  if (!Array.isArray(state['blocks'])) return invalidReplay('blocks must be an array')
112	  for (const [index, value] of state['blocks'].entries()) {
113	    if (typeof value !== 'object' || value === null || Array.isArray(value)) return invalidReplay(`block ${index} must be an object`)
114	    const block = value as Record<string, unknown>
115	    if (!['text', 'reasoning', 'tool-call'].includes(String(block['type']))) return invalidReplay(`block ${index} has an unknown type`)
116	    for (const signature of ['textSignature', 'thinkingSignature', 'thoughtSignature'] as const) {
117	      if (block[signature] !== undefined && typeof block[signature] !== 'string') return invalidReplay(`block ${index} ${signature} must be a string`)
118	    }
119	    if (block['redacted'] !== undefined && typeof block['redacted'] !== 'boolean') return invalidReplay(`block ${index} redacted must be boolean`)
120	  }
121	  return state as unknown as PiAiReplayState
122	}
123	
124	/** Convert provider-neutral blocks without trusting them as same-model replay. */
125	function foreignAssistant(message: Message): AssistantMessage {
126	  const source = message.source.kind === 'model' ? message.source : undefined
127	  const content: AssistantMessage['content'] = []
128	  for (const block of message.content) {
129	    switch (block.type) {
130	      case 'text': content.push({ type: 'text', text: block.text }); break
131	      case 'reasoning': content.push({ type: 'thinking', thinking: block.text }); break
132	      case 'tool-call': content.push({
133	        type: 'toolCall',
134	        id: block.id,
135	        name: block.name,
136	        arguments: parseArguments(block.arguments),
137	      }); break
138	      case 'image':
139	        throw new LlmError('pi-ai chat history cannot represent structured assistant image output', 'UNSUPPORTED_CONTENT')
140	      default:
141	        // plugin-added block types are not representable in pi-ai.
142	        break
143	    }
144	  }
145	  return {
146	    role: 'assistant',
147	    content,
148	    // Deliberately never equals a catalog API: absent replay state is foreign
149	    // even if source names the same provider/model as this request.
150	    api: 'dsh-foreign',
151	    provider: source?.provider ?? 'dsh-foreign',
152	    model: source?.model ?? 'dsh-foreign',
153	    usage: emptyPiUsage(),
154	    stopReason: content.some(piece => piece.type === 'toolCall') ? 'toolUse' : 'stop',
155	    timestamp: 0,
156	  }
157	}
158	
159	/** Recombine durable Harness content with validated pi-ai replay metadata. */
160	function replayedAssistant(message: Message, source: ModelMessageSource, rawState: unknown): AssistantMessage {
161	  const state = readReplayState(rawState)
162	  if (state.provider !== source.provider) return invalidReplay('provider does not match assistant source')
163	  if (state.model !== source.model) return invalidReplay('model does not match assistant source')
164	  if (state.blocks.length !== message.content.length) return invalidReplay('block count does not match assistant content')
165	  const content: AssistantMessage['content'] = message.content.map((block, index) => {
166	    const replay = state.blocks[index]
167	    if (replay === undefined || replay.type !== block.type) return invalidReplay(`block ${index} does not match assistant content`)
168	    switch (block.type) {
169	      case 'text': return {
170	        type: 'text',
171	        text: block.text,
172	        ...replay.type === 'text' && replay.textSignature !== undefined ? { textSignature: replay.textSignature } : {},
173	      }
174	      case 'reasoning': return {
175	        type: 'thinking',
176	        thinking: block.text,
177	        ...replay.type === 'reasoning' && replay.thinkingSignature !== undefined ? { thinkingSignature: replay.thinkingSignature } : {},
178	        ...replay.type === 'reasoning' && replay.redacted !== undefined ? { redacted: replay.redacted } : {},
179	      }
180	      case 'tool-call': return {
181	        type: 'toolCall',
182	        id: block.id,
183	        name: block.name,
184	        arguments: parseArguments(block.arguments),
185	        ...replay.type === 'tool-call' && replay.thoughtSignature !== undefined ? { thoughtSignature: replay.thoughtSignature } : {},
186	      }
187	      /* v8 ignore next -- readReplayState rejects unknown replay tags, so an equal plugin-added Harness tag cannot reach this switch */
188	      default: return invalidReplay(`block ${index} has an unsupported Harness type`)
189	    }
190	  })
191	  return {
192	    role: 'assistant',
193	    content,
194	    api: state.api,
195	    provider: state.provider,
196	    model: state.model,
197	    ...state.responseModel === undefined ? {} : { responseModel: state.responseModel },
198	    ...state.responseId === undefined ? {} : { responseId: state.responseId },
199	    usage: emptyPiUsage(),
200	    stopReason: state.stopReason,
201	    timestamp: 0,
202	  }
203	}
204	
205	/**
206	 * Convert one durable Harness assistant message into pi-ai history.
207	 * @param message - assistant content with required source and optional adapter-owned replay metadata.
208	 * @returns a native pi-ai assistant message reconstructed from durable content.
209	 */
210	export function toPiAssistant(message: Message): AssistantMessage {
211	  const source = message.source
212	  return source.kind !== 'model' || source.replayState === undefined
213	    ? foreignAssistant(message)
214	    : replayedAssistant(message, source, source.replayState)
215	}
