1	/**
2	 * Harness request-history conversion into pi-ai's Context vocabulary.
3	 *
4	 * @module dsh-llm-pi-ai/context
5	 */
6	
7	import { CallId, contentHasImage, LlmError } from '@deepseek-ai/dsh-llm'
8	import type { ContentBlock, GenerateOptions, Message } from '@deepseek-ai/dsh-llm'
9	import type { AttachmentStore } from '@deepseek-ai/dsh-attachment'
10	import type { Context as PiContext, ImageContent, Message as PiMessage, TextContent, Tool as PiTool } from '@earendil-works/pi-ai'
11	import { toPiAssistant } from './replay.ts'
12	
13	/** Join the text blocks of a harness message. */
14	function flattenText(message: Message): string {
15	  return message.content
16	    .filter(block => block.type === 'text')
17	    .map(block => block.text)
18	    .join('')
19	}
20	
21	
22	/** Flatten text recursively inside one tool result. */
23	function toolResultText(blocks: readonly ContentBlock[]): string {
24	  return blocks.map(block => block.type === 'text'
25	    ? block.text
26	    : block.type === 'tool-result' ? toolResultText(block.content) : '').join('')
27	}
28	
29	async function userContent(
30	  blocks: readonly ContentBlock[],
31	  attachments: AttachmentStore,
32	): Promise<string | (TextContent | ImageContent)[]> {
33	  const content: (TextContent | ImageContent)[] = []
34	  for (const block of blocks) {
35	    switch (block.type) {
36	      case 'text':
37	        if (block.text.length > 0) content.push({ type: 'text', text: block.text })
38	        break
39	      case 'image': {
40	        const stored = await attachments.readImage(block.attachment)
41	        content.push({
42	          type: 'image',
43	          data: Buffer.from(stored.data).toString('base64'),
44	          mimeType: stored.ref.mediaType,
45	        })
46	        break
47	      }
48	      case 'tool-result':
49	        {
50	          const nested = await userContent(block.content, attachments)
51	          if (typeof nested === 'string') {
52	            if (nested.length > 0) content.push({ type: 'text', text: nested })
53	          } else {
54	            content.push(...nested)
55	          }
56	        }
57	        break
58	      default:
59	        // Other merge-extensible blocks are not user-input vocabulary for pi-ai.
60	        break
61	    }
62	  }
63	  if (content.every(block => block.type === 'text')) return content.map(block => block.text).join('')
64	  return content
65	}
66	
67	function toolsOf(options: GenerateOptions): PiTool[] | undefined {
68	  return options.tools?.map(tool => ({
69	    name: tool.name,
70	    description: tool.description,
71	    // ToolSchema.parameters is a JSON Schema object; pi-ai's TSchema
72	    // (TypeBox) is structurally JSON Schema, so it assigns directly.
73	    parameters: tool.parameters,
74	  }))
75	}
76	
77	/** Assemble the request-level pi-ai context envelope shared by both conversion paths. */
78	function piContext(options: GenerateOptions, messages: PiMessage[]): PiContext {
79	  const tools = toolsOf(options)
80	  return {
81	    ...options.system !== undefined ? { systemPrompt: options.system } : {},
82	    messages,
83	    ...tools !== undefined && tools.length > 0 ? { tools } : {},
84	  }
85	}
86	
87	function textOnlyContext(options: GenerateOptions): PiContext {
88	  const toolNames = new Map<CallId, string>()
89	  const messages: PiMessage[] = []
90	  for (const message of options.messages) {
91	    if (contentHasImage(message.content)) {
92	      throw new LlmError('pi-ai image conversion requires the durable attachment service', 'UNSUPPORTED_CONTENT')
93	    }
94	    if (message.role === 'system') {
95	      messages.push({ role: 'user', content: flattenText(message), timestamp: 0 })
96	      continue
97	    }
98	    if (message.role === 'assistant') {
99	      const assistant = toPiAssistant(message)
100	      for (const block of assistant.content) if (block.type === 'toolCall') toolNames.set(CallId(block.id), block.name)
101	      messages.push(assistant)
102	      continue
103	    }
104	    const text = flattenText(message)
105	    const results = message.content.filter(block => block.type === 'tool-result')
106	    if (text.length > 0 || results.length === 0) messages.push({ role: 'user', content: text, timestamp: 0 })
107	    for (const result of results) {
108	      messages.push({
109	        role: 'toolResult',
110	        toolCallId: result.toolCallId,
111	        toolName: toolNames.get(result.toolCallId) ?? 'unknown',
112	        content: [{
113	          type: 'text',
114	          text: toolResultText(result.content) || '(no output)',
115	        }],
116	        isError: result.isError ?? false,
117	        timestamp: 0,
118	      })
119	    }
120	  }
121	  return piContext(options, messages)
122	}
123	
124	/**
125	 * Convert text-only harness history to a synchronous pi-ai Context. Tool
126	 * result names are recovered from preceding assistant tool calls.
127	 * @param options - the harness request; `options.system` maps to pi-ai's single `systemPrompt` slot.
128	 * @returns the pi-ai context; `tools` is omitted when the request declares none.
129	 */
130	export function toPiContext(options: GenerateOptions): PiContext
131	/**
132	 * Convert harness history to a pi-ai Context while resolving durable images.
133	 * Tool result names are recovered from preceding assistant tool calls.
134	 * @param options - the harness request; `options.system` maps to pi-ai's single `systemPrompt` slot.
135	 * @param attachments - durable byte resolver for image references.
136	 * @returns the asynchronously resolved pi-ai context.
137	 */
138	export function toPiContext(options: GenerateOptions, attachments: AttachmentStore): Promise<PiContext>
139	export function toPiContext(options: GenerateOptions, attachments?: AttachmentStore): PiContext | Promise<PiContext> {
140	  return attachments === undefined ? textOnlyContext(options) : toPiContextWithImages(options, attachments)
141	}
142	
143	async function toPiContextWithImages(options: GenerateOptions, attachments: AttachmentStore): Promise<PiContext> {
144	  const toolNames = new Map<CallId, string>()
145	  const messages: PiMessage[] = []
146	
147	  for (const message of options.messages) {
148	    if (message.role === 'system') {
149	      if (contentHasImage(message.content)) {
150	        throw new LlmError('pi-ai cannot represent an image in an in-history system message', 'UNSUPPORTED_CONTENT')
151	      }
152	      // pi-ai has a single systemPrompt slot; in-history system messages are
153	      // folded into user messages to preserve order (rare in practice — the
154	      // harness sends the system prompt via options.system).
155	      messages.push({ role: 'user', content: flattenText(message), timestamp: 0 })
156	      continue
157	    }
158	    if (message.role === 'assistant') {
159	      const assistant = toPiAssistant(message)
160	      for (const block of assistant.content) {
161	        if (block.type === 'toolCall') toolNames.set(CallId(block.id), block.name)
162	      }
163	      messages.push(assistant)
164	      continue
165	    }
166	    // user role: text + tool results (each result becomes its own message).
167	    const regular = message.content.filter(block => block.type !== 'tool-result')
168	    const content = await userContent(regular, attachments)
169	    const results = message.content.filter(block => block.type === 'tool-result')
170	    if (content.length > 0 || results.length === 0) {
171	      messages.push({ role: 'user', content, timestamp: 0 })
172	    }
173	    for (const result of results) {
174	      const resultContent = await userContent(result.content, attachments)
175	      messages.push({
176	        role: 'toolResult',
177	        toolCallId: result.toolCallId,
178	        toolName: toolNames.get(result.toolCallId) ?? 'unknown',
179	        content: typeof resultContent === 'string'
180	          ? [{ type: 'text', text: resultContent || '(no output)' }]
181	          : resultContent,
182	        isError: result.isError ?? false,
183	        timestamp: 0,
184	      })
185	    }
186	  }
187	
188	  return piContext(options, messages)
189	}
